<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\ContentItem; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage; use Illuminate\Support\Str;
class CmsController extends Controller {
 private function cfg($module){$cfg=config("cms.$module"); abort_unless($cfg,404); return $cfg;}
 public function index($module){$cfg=$this->cfg($module);$items=ContentItem::type($module)->orderBy('sort_order')->orderByDesc('id')->paginate(30);return view('admin.module-index',compact('module','cfg','items'));}
 public function create($module){$cfg=$this->cfg($module);$item=new ContentItem(['type'=>$module,'status'=>'Published']);return view('admin.module-form',compact('module','cfg','item'));}
 public function store(Request $r,$module){$cfg=$this->cfg($module);$item=new ContentItem;return $this->save($r,$module,$cfg,$item);}
 public function edit($module,ContentItem $item){abort_unless($item->type===$module,404);$cfg=$this->cfg($module);return view('admin.module-form',compact('module','cfg','item'));}
 public function update(Request $r,$module,ContentItem $item){abort_unless($item->type===$module,404);$cfg=$this->cfg($module);return $this->save($r,$module,$cfg,$item);}
 private function save(Request $r,$module,$cfg,$item){$rules=['title'=>'required|string|max:255','slug'=>'nullable|string|max:255','status'=>'required|string|max:50','sort_order'=>'nullable|integer'];foreach($cfg['fields'] as $f){$t=$f['type'];$rules['f_'.$f['name']] = str_starts_with($t,'image')?'nullable|image|max:5120':'nullable';} $v=$r->validate($rules);$data=$item->data?:[];foreach($cfg['fields'] as $f){$k='f_'.$f['name']; if(str_starts_with($f['type'],'image')){if($r->hasFile($k)){if(!empty($data[$f['name']])&&str_starts_with($data[$f['name']],'storage/'))Storage::disk('public')->delete(substr($data[$f['name']],8));$path=$r->file($k)->store('cms/'.$module,'public');$data[$f['name']]='storage/'.$path;}}else{$data[$f['name']]=$r->input($k);}} $item->fill(['type'=>$module,'title'=>$v['title'],'slug'=>$v['slug']?:Str::slug($v['title']).'-'.substr(md5((string)microtime(true)),0,5),'status'=>$v['status'],'sort_order'=>$v['sort_order']??0,'data'=>$data])->save();return redirect()->route('admin.module.index',$module)->with('success','Saved successfully.');}
 public function destroy($module,ContentItem $item){abort_unless($item->type===$module,404);foreach((array)$item->data as $v)if(is_string($v)&&str_starts_with($v,'storage/'))Storage::disk('public')->delete(substr($v,8));$item->delete();return back()->with('success','Deleted successfully.');}
}
